UPDATE email_templates SET subject = 'We will reschedule your meeting', text_body = 'Hi {{name}},\n\nWe missed you at the meeting and hope everything is okay. We will arrange another meeting soon. You will receive an email as soon as the new date, time, and meeting details are ready.\n\nThere is nothing you need to do right now. If you have a preferred time, you can contact the organizer and let them know.' WHERE template_key = 'missed';
UPDATE email_templates SET subject = 'We need to reschedule your meeting', text_body = 'Hi {{name}},\n\nWe need to reschedule your meeting and choose a new time. Use the button below to review the available slots and select the time that works best for you.\n\nAfter the new time is confirmed, you will receive another email with the updated meeting details.' WHERE template_key = 'reschedule';
UPDATE email_templates SET subject = 'Your meeting is cancelled: {{time}}', text_body = 'Hi {{name}},\n\nYour meeting has been cancelled. We are sorry for the inconvenience. No further action is required.\n\nIf another meeting is arranged, you will receive a separate email with the new date, time, and joining details.' WHERE template_key = 'cancelled';
